import { api, urlUtils } from '@igblsln/store';
const API_PATH = '/estimate/sectionnames/';
export const sectionNameApi = api.injectEndpoints({
    overrideExisting: false,
    endpoints: (build) => ({
        listSectionNames: build.query({
            query: ({ project, block, status, search }) => {
                const params = new URLSearchParams();
                if (project)
                    params.append('project', project.toString());
                if (block)
                    params.append('block', block.toString());
                if (status)
                    params.append('status', status);
                if (search)
                    params.append('search', search);
                params.append('without_pagination', '1');
                return {
                    url: urlUtils(API_PATH, `?${params.toString()}`),
                };
            },
            providesTags: ['SECTION_NAME'],
        }),
        addSectionNames: build.mutation({
            query(data) {
                return {
                    url: API_PATH,
                    method: 'POST',
                    body: data,
                };
            },
            invalidatesTags: ['SECTION_NAME'],
        }),
        updateSectionNames: build.mutation({
            query(data) {
                return {
                    url: `${API_PATH}${data.block_key}`,
                    method: 'PUT',
                    body: data,
                };
            },
            invalidatesTags: ['SECTION_NAME'],
        }),
        deleteSectionName: build.mutation({
            query(id) {
                return {
                    url: `${API_PATH}${id}`,
                    method: 'DELETE',
                };
            },
            invalidatesTags: ['SECTION_NAME'],
        }),
    }),
});
export const { useListSectionNamesQuery, useAddSectionNamesMutation, useUpdateSectionNamesMutation, useDeleteSectionNameMutation, } = sectionNameApi;
