export const STATUS_META = {
    NOT_STARTED: {
        label: 'Not Started',
        color: '#6b7280',
        bg: '#f3f4f6',
        icon: 'pi pi-circle-off',
    },
    IN_PROGRESS: {
        label: 'In Progress',
        color: '#2563eb',
        bg: '#eff6ff',
        icon: 'pi pi-spinner pi-spin',
    },
    PAUSED: {
        label: 'Paused',
        color: '#ea580c',
        bg: '#fff7ed',
        icon: 'pi pi-pause-circle',
    },
    STOPPED: {
        label: 'Stopped',
        color: '#dc2626',
        bg: '#fef2f2',
        icon: 'pi pi-stop-circle',
    },
    COMPLETED: {
        label: 'Completed',
        color: '#16a34a',
        bg: '#f0fdf4',
        icon: 'pi pi-check-circle',
    },
};
export const statusColor = (status) => STATUS_META[status].color;
export const statusSeverity = (status) => {
    switch (status) {
        case 'IN_PROGRESS':
            return 'info';
        case 'COMPLETED':
            return 'success';
        case 'PAUSED':
            return 'warn';
        case 'STOPPED':
            return 'error';
        default:
            return undefined;
    }
};
